import{_ as n,a0 as l,w as r,s as a,ao as i,I as o,x as e,a1 as s,A as m}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"如何在RHEL/CentOS 7.0中使用tmpfs | LCTT x X-CMD","titleTemplate":false,"description":"如何在RHEL/CentOS 7.0中使用tmpfs | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在RHEL/CentOS 7.0中使用tmpfs | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在RHEL/CentOS 7.0中使用tmpfs | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150520 How to Use tmpfs on RHEL or CentOS 7.0","title":"如何在RHEL/CentOS 7.0中使用tmpfs","tag":"201506","desc":""},"relativePath":"201506/20150520 How to Use tmpfs on RHEL or CentOS 7.0.md","filePath":"[post].md"}'),f={name:"201506/20150520 How to Use tmpfs on RHEL or CentOS 7.0.md"};function d(u,t,C,h,x,T){const p=l("Link");return r(),a("div",null,[t[13]||(t[13]=i(`<h1 id="如何在rhel-centos-7-0中使用tmpfs" tabindex="-1">如何在RHEL/CentOS 7.0中使用tmpfs <a class="header-anchor" href="#如何在rhel-centos-7-0中使用tmpfs" aria-label="Permalink to “如何在RHEL/CentOS 7.0中使用tmpfs”">​</a></h1><p>今天我们来谈谈 Centos 7 中的一个文件系统tmpfs，这是一个将所有文件和文件夹写到虚拟内存中而不是实际写到磁盘中的虚拟文件系统。这意味中tmpfs中所有的内容都是临时的，在tmpfs卸载、系统重启或者电源切断后内容都将会丢失。技术的角度上来说，tmpfs将所有的内容放在内核内部缓存中并且会调整大小来容纳文件，并可从交换空间中交换出不需要的页。</p><p>CentOS默认使用tmpfs做的几种用途可用df -h命令的输出来看：</p><pre><code># df –h
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/tmpfs1.jpg" alt="df"></p><ul><li>/dev - 含有针对所有设备的设备文件的目录</li><li>/dev/shm - 包含共享内存分配</li><li>/run - 用于系统日志</li><li>/sys/fs/cgroup - 用于cgrpups， 一个针对特定进程限制、管制和审计资源利用的内核特性</li></ul><p>显然，它也可以用作/tmp目录， 你可以用下面的两种方法来做到：</p><h3 id="使用systemctl来在-tmp中启用tmpfs" tabindex="-1">使用systemctl来在/tmp中启用tmpfs <a class="header-anchor" href="#使用systemctl来在-tmp中启用tmpfs" aria-label="Permalink to “使用systemctl来在/tmp中启用tmpfs”">​</a></h3><p>你可以使用systemctl命令在tmp目录启用tmpfs， 首先用下面的命令来检查这个特性是否可用：</p><pre><code># systemctl is-enabled tmp.mount
</code></pre><p>这会显示当先的状态，（如果未启用，）你可以使用下面的命令来启用它：</p><pre><code># systemctl enable tmp.mount
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/tmpfs3.jpg" alt="systemctl"></p><p>这会让系统控制/tmp目录并在该目录下挂载一个tmpfs文件系统。</p><h3 id="手动挂载-tmp文件系统" tabindex="-1">手动挂载/tmp文件系统 <a class="header-anchor" href="#手动挂载-tmp文件系统" aria-label="Permalink to “手动挂载/tmp文件系统”">​</a></h3><p>你可以在/etc/fstab中添加下面这行，来手工在/tmp下挂载 tmpfs。</p><pre><code>tmpfs /tmp tmpfs size=512m 0 0
</code></pre><p>接着运行这条命令</p><pre><code># mount –a
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/05/tmpfs2.jpg" alt="df"></p><p>这应该就会在df -h中显示tmpfs了，同样也会在你下次重启时自动挂载。</p><h3 id="立即创建tmpfs" tabindex="-1">立即创建tmpfs <a class="header-anchor" href="#立即创建tmpfs" aria-label="Permalink to “立即创建tmpfs”">​</a></h3><p>如果由于一些原因，你需要在一个文件夹下立即创建tmpfs，你可以使用下面的命令：</p><pre><code># mount -t tmpfs -o size=1G tmpfs /mnt/mytmpfs
</code></pre><p>当然你可以在size选项中指定你希望的大小和希望的挂载点，只要记住是有效的目录就行了。</p><hr>`,26)),o("p",null,[t[1]||(t[1]=e("via: ",-1)),s(p,{href:"http://linoxide.com/file-system/use-tmpfs-rhel-centos-7-0/"},{default:m(()=>[...t[0]||(t[0]=[e("http://linoxide.com/file-system/use-tmpfs-rhel-centos-7-0/",-1)])]),_:1})]),o("p",null,[t[5]||(t[5]=e("作者：",-1)),s(p,{href:"http://linoxide.com/author/adriand/"},{default:m(()=>[...t[2]||(t[2]=[e("Adrian Dinu",-1)])]),_:1}),t[6]||(t[6]=e(" 译者：",-1)),s(p,{href:"https://github.com/geekpi"},{default:m(()=>[...t[3]||(t[3]=[e("geekpi",-1)])]),_:1}),t[7]||(t[7]=e(" 校对：",-1)),s(p,{href:"https://github.com/wxy"},{default:m(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=e("本文由 ",-1)),s(p,{href:"https://github.com/LCTT/TranslateProject"},{default:m(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原创翻译，",-1)),s(p,{href:"https://linux.cn/"},{default:m(()=>[...t[9]||(t[9]=[e("Linux中国",-1)])]),_:1}),t[12]||(t[12]=e(" 荣誉推出",-1))])])}const b=n(f,[["render",d]]);export{L as __pageData,b as default};
